insert into public.content_items (content_type, status, title, slug, excerpt, body, published_at)
values
  ('page', 'published', 'Start Here', 'start-here', 'Begin with light, space, climate, and a manageable first crop.', '{"stage":"foundation","navigation":{"section":"grow","subsection":"plant-guides"}}', now()),
  ('guide', 'draft', 'Growing herbs on a small balcony', 'growing-herbs-small-balcony', 'A future Natura guide used to validate the editorial workflow.', '{"stage":"sample"}', null),
  ('plant', 'published', 'Cherry tomato', 'cherry-tomato', 'A generous summer crop for a bright balcony.', '{"overview":"Compact cherry tomatoes reward consistent watering, a large container, and the sunniest position you can offer.","category":"Vegetable","botanical_name":"Solanum lycopersicum var. cerasiforme","difficulty":"Moderate","sunlight":"6–8 hours","pot_size":"20–30 L","watering":"Deep and regular","harvest":"60–80 days","season":"Late spring to early autumn","image":"/images/cherry-tomato.jpg","image_alt":"A compact cherry tomato plant fruiting in a terracotta container","suitable_for":["Sunny balconies","Patios","Large containers"],"care":[{"title":"Give it real sun","text":"Choose the warmest position available, with at least six hours of direct light."},{"title":"Keep moisture even","text":"Water deeply when the top layer begins to dry."}],"watch_for":[{"title":"Leaf curl","text":"Check moisture and recent conditions before treating for pests."}],"navigation":{"section":"grow","subsection":"vegetables"}}', now()),
  ('plant', 'published', 'Genovese basil', 'genovese-basil', 'Fragrant leaves for a warm windowsill or sheltered balcony.', '{"overview":"Basil grows quickly when warmth, bright light, and steady moisture come together—and regular harvesting keeps it productive.","category":"Herb","botanical_name":"Ocimum basilicum Genovese","difficulty":"Easy","sunlight":"4–6 hours","pot_size":"3–5 L","watering":"Evenly moist","harvest":"30–45 days","season":"Warm months or indoors","image":"/images/genovese-basil.jpg","image_alt":"A lush Genovese basil plant in an ivory ceramic pot by a window","suitable_for":["Windowsills","Sheltered balconies","Kitchen gardens"],"care":[{"title":"Prioritise warmth","text":"Keep basil above 15°C and away from cold draughts."},{"title":"Harvest from the top","text":"Pinch stems just above a pair of leaves to encourage branching."}],"watch_for":[{"title":"Drooping leaves","text":"Check the compost before changing the watering routine."}],"navigation":{"section":"grow","subsection":"herbs"}}', now()),
  ('plant', 'published', 'Balcony strawberry', 'balcony-strawberry', 'Sweet harvests from a compact pot, trough, or hanging basket.', '{"overview":"Strawberries suit compact spaces beautifully, provided their crowns stay above the soil and their roots never sit in water.","category":"Fruit","botanical_name":"Fragaria × ananassa","difficulty":"Easy","sunlight":"6+ hours","pot_size":"3 L per plant","watering":"Regular at soil level","harvest":"12–16 weeks","season":"Spring to midsummer","image":"/images/balcony-strawberry.jpg","image_alt":"A fruiting strawberry plant in a weathered terracotta bowl on a balcony","suitable_for":["Balcony ledges","Hanging baskets","Window boxes"],"care":[{"title":"Keep crowns clear","text":"Keep the crown level with the surface and never bury it."},{"title":"Aim for morning sun","text":"Six hours of light supports flowering and flavour."}],"watch_for":[{"title":"Grey mould","text":"Improve airflow and avoid wetting fruit late in the day."}],"navigation":{"section":"grow","subsection":"fruit"}}', now());
insert into public.content_items (content_type, status, title, slug, excerpt, body, seo_title, seo_description, published_at) values ('problem','published','Yellow leaves in container plants','yellow-leaves-container-plants','Use leaf position, watering history, drainage, and growth pattern to narrow the likely cause of yellow leaves.','{"overview":"Yellow leaves are a symptom, not a diagnosis. Start with where yellowing appears, how quickly it developed, and what changed in watering, drainage, light, temperature, or feeding.","navigation":{"section":"plant-care","subsection":"plant-problems"},"sources":[],"seo_keyword_strategy":{"focus_keyword":"why are my container plant leaves turning yellow","supporting_keywords":["yellow leaves overwatering","plant leaves yellow nutrient deficiency","yellow leaves poor drainage"],"search_intent":"informational"}}','Why Container Plant Leaves Turn Yellow','Yellow leaves can signal watering, drainage, root, light, or nutrient problems. Compare the pattern before changing your plant care routine.',now());
insert into public.problem_profiles (content_id,category,urgency,symptoms,likely_causes,verification_steps,recommended_actions,warnings) select id,'watering','moderate',array['Older lower leaves turn yellow','Compost stays wet for several days','New growth may appear pale or slow'],'[{"title":"Excess water or poor drainage","text":"Roots short of oxygen cannot function normally."},{"title":"Natural leaf ageing","text":"One or two older leaves may yellow naturally."}]','[{"title":"Check moisture below the surface","text":"Test several centimetres deep."},{"title":"Inspect drainage","text":"Confirm water can leave the pot."}]','[{"title":"Correct the condition","text":"Adjust care only after checking the pattern."},{"title":"Remove fully yellow leaves","text":"Keep partly green leaves when healthy."}]',array['Do not fertilise a waterlogged plant.'] from public.content_items where slug='yellow-leaves-container-plants';
insert into public.problem_plant_links (problem_content_id,plant_content_id) select problem.id,plant.id from public.content_items problem cross join public.content_items plant where problem.slug='yellow-leaves-container-plants' and plant.slug in ('cherry-tomato','genovese-basil','balcony-strawberry');
insert into public.content_items (content_type,status,title,slug,excerpt,body,seo_title,seo_description,published_at) values ('guide','published','Start a balcony herb garden','start-balcony-herb-garden','Build a practical first herb garden by reading your light, choosing suitable containers, and starting with a manageable group of plants.','{"overview":"A useful balcony herb garden begins with honest observation: how many hours of direct light reach the space, how exposed it is to wind, and how easily you can water. Start small, use containers with drainage, and group plants only when their moisture needs are compatible.","navigation":{"section":"small-space-gardening","subsection":"balcony"},"sources":[],"seo_keyword_strategy":{"focus_keyword":"how to start a balcony herb garden","supporting_keywords":["best herbs for a balcony","herb garden container size","balcony herb garden for beginners"],"search_intent":"how-to"}}','How to Start a Balcony Herb Garden','Start a balcony herb garden with practical advice on light, containers, drainage, watering, plant choice, wind protection, and an easy first layout.',now()) on conflict (slug) do nothing;
insert into public.guide_profiles (content_id,guide_type,difficulty,estimated_time_minutes,audience,prerequisites,materials,steps,tips,warnings) select id,'balcony','easy',45,'First-time balcony gardeners with a small sunny or partly sunny outdoor space.',array['Observe the balcony light for a full day','Confirm that containers can drain safely','Choose a reachable watering point'],array['Three containers with drainage holes','Peat-free multipurpose compost','Saucers or pot feet where appropriate','Two or three compatible herbs','Watering can'],'[{"title":"Map the light and wind","text":"Record direct sun in the morning, midday, and afternoon."},{"title":"Choose fewer, better containers","text":"Use stable pots with drainage holes and enough compost volume."},{"title":"Match herbs to the conditions","text":"Choose plants for the measured light and keep different watering needs separate."},{"title":"Plant at the correct depth","text":"Keep each plant at its nursery depth, firm gently, and water once."},{"title":"Build a simple care rhythm","text":"Check moisture before watering and harvest little and often."}]',array['Place frequently harvested herbs closest to the door','Use separate pots for herbs with very different watering needs'],array['Check balcony load and building rules before adding heavy containers','Secure light pots where wind could dislodge them'] from public.content_items where slug='start-balcony-herb-garden' on conflict (content_id) do nothing;
insert into public.guide_plant_links (guide_content_id,plant_content_id) select guide.id,plant.id from public.content_items guide cross join public.content_items plant where guide.slug='start-balcony-herb-garden' and plant.slug='genovese-basil' on conflict do nothing;
insert into public.content_items (content_type,status,title,slug,excerpt,body,seo_title,seo_description,published_at) values ('calendar','published','Mediterranean container planting calendar','mediterranean-container-calendar','A practical month-by-month rhythm for edible containers in a mild Mediterranean climate, with local weather checks built into every decision.','{"overview":"Use this calendar as a sequence of observations, not fixed instructions. Coastal exposure, altitude, wind, heat, container size, and unusual weather can move a task by several weeks.","navigation":{"section":"planting-calendar","subsection":"monthly-calendars"},"sources":[],"seo_keyword_strategy":{"focus_keyword":"mediterranean container planting calendar","supporting_keywords":["what to plant each month mediterranean climate","balcony planting calendar","container vegetable calendar"],"search_intent":"informational"}}','Mediterranean Container Planting Calendar','Plan edible containers month by month in a Mediterranean climate, including sowing, planting, harvesting, care, heat protection, and local-weather checks.',now()) on conflict (slug) do nothing;
insert into public.calendar_profiles (content_id,climate,hemisphere,space_type,scope_note,warnings) select id,'mediterranean','northern','container','For mild-winter Northern Hemisphere locations with hot, dry summers and container growing.',array['Local frost, heatwaves, altitude, wind, and coastal exposure can shift tasks by several weeks.'] from public.content_items where slug='mediterranean-container-calendar' on conflict (content_id) do nothing;
insert into public.calendar_entries (calendar_content_id,month,activity_type,title,description,priority,sort_order) select calendar.id,entry.month,entry.activity_type,entry.title,entry.description,entry.priority,1 from public.content_items calendar cross join (values (1,'plan','Review light and drainage','Map winter sun and clean drainage holes.','normal'),(2,'sow-indoors','Start tomatoes under protection','Sow only where warmth and strong light are reliable.','normal'),(3,'sow-outdoors','Sow cool-season crops','Try radish, salad leaves, coriander, or chard.','normal'),(4,'plant','Move tender crops out gradually','Harden plants off and wait through unusual cold.','high'),(5,'plant','Complete warm-season planting','Plant tomatoes and basil when nights are suitable.','high'),(6,'care','Shift to heat-aware watering','Check early and water deeply when needed.','high'),(7,'protect','Protect roots during extreme heat','Shade dark pots and avoid reflected afternoon heat.','high'),(8,'sow-indoors','Prepare autumn salad seedlings','Start small batches away from extreme heat.','normal'),(9,'sow-outdoors','Sow autumn salads','Use salad leaves, coriander, and radish as heat eases.','high'),(10,'care','Reduce watering frequency','Containers dry more slowly as temperatures fall.','normal'),(11,'protect','Prepare for wind and cold rain','Secure pots and improve drainage.','high'),(12,'plan','Record what worked','Note successful positions, containers, and varieties.','normal')) as entry(month,activity_type,title,description,priority) where calendar.slug='mediterranean-container-calendar' on conflict do nothing;
insert into public.calendar_plant_links (calendar_content_id,plant_content_id) select calendar.id,plant.id from public.content_items calendar cross join public.content_items plant where calendar.slug='mediterranean-container-calendar' and plant.slug in ('cherry-tomato','genovese-basil','balcony-strawberry') on conflict do nothing;
insert into public.content_items (content_type,status,title,slug,excerpt,body,seo_title,seo_description,published_at) values ('review','published','Self-watering container types for balconies','self-watering-container-types-balconies','Compare three self-watering container systems for a small balcony, including drainage safety, water visibility, heat resilience, and maintenance.','{"overview":"Self-watering containers can reduce daily watering pressure, but the label covers very different systems. We compared three common formats through documented design characteristics and practical balcony constraints. This is a researched comparison, not a hands-on product test.","navigation":{"section":"reviews","subsection":"containers"},"sources":[],"seo_keyword_strategy":{"focus_keyword":"best self watering container type for balcony","supporting_keywords":["self watering planter comparison","wicking pot for balcony","self watering container drainage"],"search_intent":"comparison"}}','Self-Watering Container Types for Balconies','Compare built-in reservoirs, wick inserts, and double-pot systems for balcony growing, including drainage, heat, maintenance, and small-space suitability.',now()) on conflict (slug) do nothing;
insert into public.review_profiles (content_id,review_type,category,evidence_level,methodology,disclosure_type,disclosure_text,verdict,best_for) select id,'comparison','containers','researched','We compared the design of three common self-watering container formats against five balcony-specific criteria. Scores reflect documented features and predictable use constraints; Natura did not conduct a controlled growing trial for this article.','independent','Natura has no commercial relationship with the systems compared here. No product was supplied and no affiliate link is included.','A built-in reservoir planter is the clearest all-round choice when it includes a visible overflow and water-level indicator. A modular wick insert is more flexible for existing pots, while a double-pot setup suits experimentation on a smaller budget.',array['Gardeners who miss occasional watering days','Sunny balconies where containers dry quickly','Small spaces that need controlled drainage'] from public.content_items where slug='self-watering-container-types-balconies' on conflict (content_id) do nothing;
insert into public.review_criteria (review_content_id,name,description,weight,sort_order) select review.id,criterion.name,criterion.description,criterion.weight,criterion.sort_order from public.content_items review cross join (values ('Drainage safety','How clearly the system prevents prolonged waterlogging and handles overflow.',30,1),('Water visibility','How easily a gardener can see or infer the remaining reservoir level.',20,2),('Heat resilience','How well the design limits rapid heating and evaporation on an exposed balcony.',20,3),('Maintenance','The effort needed to refill, clean, inspect, and reset the system.',15,4),('Small-space fit','Stability, footprint, and practicality in a compact outdoor area.',15,5)) as criterion(name,description,weight,sort_order) where review.slug='self-watering-container-types-balconies' and not exists (select 1 from public.review_criteria existing where existing.review_content_id=review.id);
insert into public.review_products (review_content_id,name,price_note,verdict_label,overall_score,pros,cons,specifications,is_recommended,sort_order) select review.id,product.name,product.price_note,product.verdict_label,product.overall_score,product.pros,product.cons,product.specifications::jsonb,product.is_recommended,product.sort_order from public.content_items review cross join (values ('Built-in reservoir planter','Usually the highest initial cost','Best all-round format',8.6,array['Integrated overflow is easy to inspect','Optional level gauges make refilling clearer','Stable single-piece design'],array['Takes more storage space','Reservoir can still overheat in dark containers'],'{"Typical setup":"Planter with separated reservoir","Best feature":"Visible overflow and optional gauge"}',true,1),('Modular wick insert','Mid-range; reuses a compatible outer pot','Best for adapting existing pots',7.8,array['Flexible across several pot styles','Wicks can be replaced','Easy to dismantle for cleaning'],array['Fit varies by outer pot','Requires careful overflow planning'],'{"Typical setup":"Insert, platform, and wicks","Best feature":"Adaptability"}',false,2),('Double-pot cachepot setup','Lowest-cost experimental option','Best budget experiment',6.9,array['Can be assembled from existing containers','Simple principle','Easy to prototype at small scale'],array['Water level is often difficult to see','Poorly matched pots can become unstable','Drainage safety depends on the setup'],'{"Typical setup":"Nursery pot above a separate reservoir","Best feature":"Low entry cost"}',false,3)) as product(name,price_note,verdict_label,overall_score,pros,cons,specifications,is_recommended,sort_order) where review.slug='self-watering-container-types-balconies' and not exists (select 1 from public.review_products existing where existing.review_content_id=review.id);
insert into public.review_product_scores (product_id,criterion_id,score,note) select product.id,criterion.id,case product.sort_order when 1 then (array[9.0,9.0,7.5,8.5,8.5])[criterion.sort_order] when 2 then (array[7.5,7.0,8.0,8.0,8.5])[criterion.sort_order] else (array[6.0,5.5,7.5,7.0,7.5])[criterion.sort_order] end,'' from public.review_products product join public.review_criteria criterion on criterion.review_content_id=product.review_content_id join public.content_items review on review.id=product.review_content_id where review.slug='self-watering-container-types-balconies' on conflict (product_id,criterion_id) do nothing;
